function getPolandLocaleCopy(locale) {
  return POLAND_LOCALE_COPY[normalizeLocale(locale)] || POLAND_LOCALE_COPY.en;
}

function resolveCountryCopy(locale, countryName) {
  const raw = getPolandLocaleCopy(locale);
  const resolved = {};
  for (const [key, value] of Object.entries(raw)) {
    resolved[key] = String(value).replaceAll('{country}', countryName);
  }
  return resolved;
}


