    'Each full-premium country is generated from the same strict contract: useful local tools, readable visual identity, field-level debugging, and no fake official lookup promises.': 'Кожна full-premium країна створюється за тим самим строгим контрактом: корисні локальні інструменти, читабельна візуальна ідентичність, дебаг на рівні полів і жодних фальшивих обіцянок офіційного lookup.',
