    ' Parser Pro': ' — ' + words.parser + ' Pro',
    ' Validator': ' — ' + words.validator,
    ' Inspector': ' — ' + words.inspector,
    ' Workbench': ' — ' + words.workbench,
    ' Helper': ' — ' + words.helper,
    ' Formatter': ' — ' + words.formatter,
    ' Converter': ' — ' + words.converter,
    ' Generator': ' — ' + words.generator,
