function applyCountryToolSummaryPatterns(content, locale) {
  let next = content;
  for (const [pattern, replacement] of [
    ...(COUNTRY_TOOL_SUMMARY_PATTERNS[locale] || []),
    ...(COUNTRY_TOOL_SUMMARY_EXTRA_PATTERNS[locale] || [])
  ]) {
    next = next.replace(pattern, replacement);
  }
  return next;
}

function localizeCountryNames(content, locale) {
  const names = COUNTRY_NAMES[locale] || {};
  let next = content;
  for (const [from, to] of Object.entries(names)) {
    const pattern = from === 'Europe' ? /\bEurope\b(?!\/)/g : new RegExp(`\\b${escapeRegExp(from)}\\b`, 'g');
    next = next.replace(pattern, to);
  }
  return next;
}

