    zugferd: { es: 'ZUGFeRD - asistente', 'pt-BR': 'ZUGFeRD - assistente', de: 'ZUGFeRD - Helfer', fr: 'ZUGFeRD - assistant', pl: 'ZUGFeRD - pomocnik', uk: 'ZUGFeRD - помічник' },
