function applyToolTitleTermTranslations(content, locale) {
  return applyLiteralMap(content, TOOL_TITLE_TERM_TRANSLATIONS[locale]);
}


function localizedCountryName(englishName, locale) {
  return (COUNTRY_NAMES[locale] && COUNTRY_NAMES[locale][englishName]) || englishName;
}

function applyParameterizedCountryTranslations(content, locale) {
  const t = UI[locale];
  if (!t) return content;
  const common = COMMON_LABELS[locale] || {};
  const countryPattern = '(Poland|Brazil|Spain|Germany)';
  let next = content;
  const polandCopy = resolveCountryCopy(locale, localizedCountryName('Poland', locale));
  next = replaceAllLiteral(next, 'Search PESEL, NIP, REGON, KRS, BLIK...', polandCopy.searchPlaceholder);
  next = replaceAllLiteral(next, 'Search PESEL, NIP, REGON, KRS, BLIK…', polandCopy.searchPlaceholder);
  next = next.replace(new RegExp('Search across available ' + countryPattern + ' workbenches on this page\\.', 'g'), (_, country) => {
    const name = localizedCountryName(country, locale);
    return resolveCountryCopy(locale, name).searchHint;
  });
  next = next.replace(new RegExp('Copy ' + countryPattern + ' constants instantly', 'g'), (_, country) => {
    const name = localizedCountryName(country, locale);
    return resolveCountryCopy(locale, name).quickActionsTitle;
  });
  next = next.replace(new RegExp(countryPattern + ' workbench suite', 'g'), (_, country) => {
    const name = localizedCountryName(country, locale);
    return resolveCountryCopy(locale, name).catalogTitle;
  });
  next = next.replace(new RegExp(countryPattern + ' country outline centered on canvas, derived from Natural Earth public-domain admin-0 geometry\\.', 'g'), (_, country) => {
    const name = localizedCountryName(country, locale);
    const copy = resolveCountryCopy(locale, name);
    return copy.shapeCaption + ' - ' + copy.officialAdministrativeOutline + '.';
  });
  next = next.replace(new RegExp(countryPattern + ' country outline', 'g'), (_, country) => resolveCountryCopy(locale, localizedCountryName(country, locale)).shapeCaption);
  next = next.replace(/Polish account, transfer (&amp;|&) clearing standards/g, () => {
    if (locale === 'pl') return 'Polskie standardy kont, przelewów i rozliczeń';
    if (locale === 'de') return 'Polnische Konto-, Überweisungs- und Clearing-Standards';
    if (locale === 'es') return 'Estándares polacos de cuentas, transferencias y compensación';
    if (locale === 'pt-BR' || locale === 'pt-PT') return 'Padrões poloneses de contas, transferências e compensação';
    return resolveCountryCopy(locale, localizedCountryName('Poland', locale)).paymentIntentTitle;
  });
  next = next.replace(/Polish payment rails (&amp;|&) offline helpers/g, () => {
    if (locale === 'pl') return 'Polskie systemy płatności i pomocniki offline';
    if (locale === 'de') return 'Polnische Zahlungswege und Offline-Helfer';
    if (locale === 'es') return 'Redes de pago polacas y ayudas offline';
    if (locale === 'pt-BR' || locale === 'pt-PT') return 'Trilhos de pagamento poloneses e auxiliares offline';
    return resolveCountryCopy(locale, localizedCountryName('Poland', locale)).paymentIntentTitle;
  });
  next = next.replace(new RegExp(countryPattern + ' account, transfer (&amp;|&) banking standards', 'g'), (_, country) => resolveCountryCopy(locale, localizedCountryName(country, locale)).paymentIntentTitle);
  next = next.replace(new RegExp(countryPattern + ' payment rails (&amp;|&) offline helpers', 'g'), (_, country) => resolveCountryCopy(locale, localizedCountryName(country, locale)).paymentIntentTitle);
  next = next.replace(/IBAN, domestic account context, BIC\/SWIFT, SEPA or local clearing notes, and payment-ready developer workflows\./g, () => resolveCountryCopy(locale, localizedCountryName('Poland', locale)).paymentIntentBody);
  next = next.replace(/Local payment systems, card context, bank transfer references, currency formatting, and browser-only payment data helpers\./g, () => resolveCountryCopy(locale, localizedCountryName('Poland', locale)).paymentIntentBody);
  next = applyLiteralMap(next, common);
  return next;
}


function localizeSeoAndStructuredData(content, locale, routePath) {
  let next = content;
  next = next.replace(/<html\s+lang="[^"]+">/i, `<html lang="${locale}">`);
  next = next.replace(/<link rel="canonical" href="https:\/\/validohub\.com\/en\//g, `<link rel="canonical" href="https://validohub.com/${locale}/`);
  next = next.replace(/("url"\s*:\s*")https:\/\/validohub\.com\/en\//g, `$1https://validohub.com/${locale}/`);
  next = next.replace(/("url"\s*:\s*")https:\\\/\\\/validohub\.com\\\/en\\\//g, `$1https:\/\/validohub.com\/${locale}\/`);
  next = next.replace(/"inLanguage"\s*:\s*"en"/g, `"inLanguage":"${locale}"`);
  next = next.replace(/content="\/en\//g, `content="/${locale}/`);
  if (routePath) {
    next = next.replace(/"url":"https:\/\/validohub\.com[^"]+"/g, `"url":"https://validohub.com${routePath}"`);
  }
  return next;
}

function repairStructuredDataKeys(content) {
  return String(content || '')
    .replace(/"application(?:Cat[eé]gorie|Kategorie|Kategoria|Категорія)"\s*:/g, '"applicationCategory":')
    .replace(/"operating(?:System|Syst[eè]me|System|Sistema|Система)"\s*:/g, '"operatingSystem":');
}

export function rewriteHrefLocale(content, locale, routeRegistry) {
  return content.replace(/href="\/en\/([^"]*)"/g, (match, target) => {
    const normalizedTarget = String(target || '').replace(/^\/+/, '');
    const localizedCandidate = `/${locale}/${normalizedTarget}`;
    const normalizedLocalized = localizedCandidate.endsWith('/') ? localizedCandidate : `${localizedCandidate}/`;
    if (!routeRegistry.has(normalizedLocalized)) return match;
    return `href="${localizedCandidate}"`;
  });
}

function injectAlternateLinks(content, currentPath, routeRegistry, locales) {
  const { suffix } = splitRouteLocale(currentPath);
  const alternateTags = [];
  for (const localeCode of locales) {
    const candidatePath = routeForLocale(localeCode, suffix);
    if (routeRegistry.has(candidatePath)) {
      alternateTags.push(`<link rel="alternate" hreflang="${localeCode}" href="https://validohub.com${candidatePath}">`);
    }
  }
  const englishPath = routeForLocale('en', suffix);
  if (routeRegistry.has(englishPath)) {
    alternateTags.push(`<link rel="alternate" hreflang="x-default" href="https://validohub.com${englishPath}">`);
  }

  let next = content.replace(/<link rel="alternate" hreflang="[^"]+" href="[^"]+">\s*/gi, '');
  if (alternateTags.length) {
    next = next.replace('</head>', `  ${alternateTags.join('\n  ')}\n</head>`);
  }
  return next;
}

export function translateVisibleHtml(content, locale) {
  const normalized = normalizeLocale(locale);
  if (normalized === 'en') return content;
  const { protectedHtml, blocks } = protectBlocks(content);
  let next = protectedHtml;
  next = applyCommonUiTranslations(next, normalized);
  next = applyLiteralMap(next, IDENTIFIER_REFERENCE_REPLACEMENTS[normalized]);
  next = applyLiteralMap(next, GUIDE_REFERENCE_REPLACEMENTS[normalized]);
  next = applyCategoryNavTranslations(next, normalized);
  next = applyProductionLocaleReplacements(next, normalized);
  next = applySemanticCopyTranslations(next, normalized);
  next = applyGeneratedToolTitleTranslations(next, normalized);
  next = applyCountryToolSummaryPatterns(next, normalized);
  next = applyLiteralMap(next, SECTION_LABELS[normalized]);
  next = applyParameterizedCountryTranslations(next, normalized);
  next = applyCountryTitleTranslations(next, normalized);
  next = applyDocumentationSummaryTranslations(next, normalized);
  next = applyCountryPortalTaxonomyTranslations(next, normalized);
  next = applyToolTitleTermTranslations(next, normalized);
  next = applyCountryPageTranslations(next, normalized);
  next = applyGeneratedToolTitleTranslations(next, normalized);
  next = applyCountrySummaryPatternTranslations(next, normalized);
  next = applySemanticCopyTranslations(next, normalized);
  next = applyLocalizedCountryLinkText(next, normalized);
  next = localizeCountryNames(next, normalized);
  next = applyCountryPortalTaxonomyTranslations(next, normalized);
  next = applyToolTitleTermTranslations(next, normalized);
  next = applyProductionFinalRepairs(next, normalized);
  next = applyLiteralMap(next, IDENTIFIER_REFERENCE_REPLACEMENTS[normalized]);
  next = applyLiteralMap(next, GUIDE_REFERENCE_REPLACEMENTS[normalized]);
  next = repairCountryCatalogRows(next, normalized);
  next = repairRelatedCountryLinkCards(next, normalized);
  let restored = restoreBlocks(next, blocks);
  restored = applyGeneratedToolTitleTranslations(restored, normalized);
  restored = applyCountryToolSummaryPatterns(restored, normalized);
  restored = applyToolTitleTermTranslations(restored, normalized);
  restored = applyLiteralMap(restored, IDENTIFIER_REFERENCE_REPLACEMENTS[normalized]);
  restored = applyLiteralMap(restored, GUIDE_REFERENCE_REPLACEMENTS[normalized]);
  restored = repairCountryCatalogRows(restored, normalized);
  restored = repairRelatedCountryLinkCards(restored, normalized);
  return repairStructuredDataKeys(applyCountryProtectedValueTranslations(restored, normalized));
}

export async function applyFinalLocalizationPass(routeRegistry, siteRoot, locales, options = {}) {
  const configuredLocales = locales && locales.length ? locales : ['en'];
  const forceRefresh = Boolean(options.forceRefresh);
  const concurrency = Math.max(1, Number(options.concurrency || process.env.VALIDOHUB_LOCALIZATION_CONCURRENCY || 32));
  const runBatches = async (items, worker) => {
    for (let index = 0; index < items.length; index += concurrency) {
      await Promise.all(items.slice(index, index + concurrency).map(worker));
    }
  };
  hydrateCountryNamesFromRegistry(routeRegistry, configuredLocales);
  ensureLocalizedRoutes(routeRegistry, siteRoot, configuredLocales);
  const includeSuffixes = new Set((options.includeSuffixes || []).map(suffix => {
    const normalized = String(suffix || '/').trim();
    if (!normalized || normalized === '/') return '/';
    const withLead = normalized.startsWith('/') ? normalized : `/${normalized}`;
    return withLead.endsWith('/') ? withLead : `${withLead}/`;
  }));
  const shouldProcessRoute = (route) => {
    if (!includeSuffixes.size) return true;
    return includeSuffixes.has(splitRouteLocale(route.path).suffix);
  };
  const routesToProcess = routeRegistry.getAll().filter(shouldProcessRoute);
  await runBatches(routesToProcess, async (route) => {
    const { locale, suffix } = splitRouteLocale(route.path);
    if (locale === 'en') return;

    const englishPath = routeForLocale('en', suffix);
    const englishRoute = routeRegistry.get(englishPath);
    if (!englishRoute || !(await pathExists(englishRoute.outputPath))) return;

    const shouldRefreshFromNodeSource = englishRoute.sourceOwner === 'node' || ['country', 'countries'].includes(englishRoute.type);
    if ((await pathExists(route.outputPath)) && !shouldRefreshFromNodeSource && !forceRefresh) return;

    let content = await readFile(englishRoute.outputPath, 'utf8');
    content = rewriteHrefLocale(content, locale, routeRegistry);
    content = localizeSeoAndStructuredData(content, locale, route.path);
    content = translateVisibleHtml(content, locale);
    await mkdir(dirname(route.outputPath), { recursive: true });
    await writeFile(route.outputPath, content, 'utf8');
    console.log(`✓ Generated localized route: ${route.path}`);
  });

  await runBatches(routesToProcess, async (route) => {
    if (!(await pathExists(route.outputPath))) return;
    const { locale } = splitRouteLocale(route.path);
    let content = await readFile(route.outputPath, 'utf8');
    const original = content;
    if (locale !== 'en') {
      content = rewriteHrefLocale(content, locale, routeRegistry);
      content = localizeSeoAndStructuredData(content, locale, route.path);
      content = translateVisibleHtml(content, locale);
    }
    content = repairStructuredDataKeys(content);
    content = injectAlternateLinks(content, route.path, routeRegistry, configuredLocales);
    if (content !== original) {
      await writeFile(route.outputPath, content, 'utf8');
    }
  });
}

export function localizedRuntimeLabels(localeCode) {
  return UI[normalizeLocale(localeCode)] || {};
}
